package com.guocheng.mediapocket;
 import org.json.*;import java.util.*;
final class FusionPlaybackRules {
 static String episodeKey(String name){String value=name.replaceAll("(?i)\\.(mkv|mp4|avi|ts|m4v)$","").trim();java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i)S(\\d+)E(\\d+)").matcher(value);if(m.find())return "s"+Integer.parseInt(m.group(1))+"e"+Integer.parseInt(m.group(2));return value.toLowerCase(Locale.ROOT).replaceAll("\\s+","");}
 static boolean sameFilm(String candidate,String candidateYear,String wanted,String wantedYear){return MediaMatchRules.key(candidate).equals(MediaMatchRules.key(wanted))&&(wantedYear.isEmpty()||(!candidateYear.isEmpty()&&wantedYear.equals(candidateYear)));}
 static final class Episode {final int season,number;Episode(int s,int n){season=s;number=n;}}
 static int number(String text){try{return Integer.parseInt(text);}catch(Exception ignored){}String digits="零一二三四五六七八九";text=text.replace('〇','零').replace('两','二');int total=0,current=0;if(text.indexOf('十')<0&&text.indexOf('百')<0){for(char c:text.toCharArray()){int n=digits.indexOf(c);if(n<0)return -1;total=total*10+n;}return total;}for(char c:text.toCharArray()){int n=digits.indexOf(c);if(n>=0)current=n;else if(c=='十'||c=='百'){total+=(current==0?1:current)*(c=='十'?10:100);current=0;}else return -1;}return total+current;}
 static Episode episode(String text,String context){java.util.regex.Matcher se=java.util.regex.Pattern.compile("(?i)S(\\d+)E(\\d+)").matcher(text);if(se.find())return new Episode(number(se.group(1)),number(se.group(2)));java.util.regex.Matcher season=java.util.regex.Pattern.compile("(?i)(?:第\\s*([零〇一二两三四五六七八九十百0-9]+)\\s*季|(?:Season\\s+|\\bS)([0-9]+)\\b)").matcher(text+" "+context);int s=season.find()?number(season.group(1)==null?season.group(2):season.group(1)):-1;java.util.regex.Matcher ep=java.util.regex.Pattern.compile("第\\s*([零〇一二两三四五六七八九十百0-9]+)\\s*集").matcher(text);if(ep.find())return new Episode(s,number(ep.group(1)));ep=java.util.regex.Pattern.compile("(?i)^\\s*(?:EP?|Episode\\s*)?([0-9]{1,3})(?:\\s*集|\\.(?:mkv|mp4|ts)|\\s*$)").matcher(text);return new Episode(s,ep.find()?number(ep.group(1)):-1);}
 static boolean sameEpisode(String wanted,String candidate,String flag){Episode a=episode(wanted,""),b=episode(candidate,flag);if(a.number>0&&b.number>0)return a.season>=0&&b.season>=0&&a.season==b.season&&a.number==b.number;return episodeKey(wanted).equals(episodeKey(candidate));}
 static boolean differentEpisode(String wanted,String candidate,String flag){Episode a=episode(wanted,""),b=episode(candidate,flag);return a.number>0&&b.number>0&&(a.number!=b.number||(a.season>=0&&b.season>=0&&a.season!=b.season));}
 static final class Route {final String flag,name,value;Route(String f,String n,String v){flag=f;name=n;value=v;}}
 static List<Route> routeList(String flagText,String groupText,String wanted,boolean episodic,boolean confirmedOnly,String title){ArrayList<Route> out=new ArrayList<>();String[] flags=flagText.split("\\$\\$\\$",-1),groups=groupText.split("\\$\\$\\$",-1);for(int g=0;g<groups.length;g++)for(String encoded:groups[g].split("#")){String[] ep=encoded.split("\\$",2);if(ep.length<2||ep[1].isEmpty())continue;String flag=g<flags.length?flags[g]:"线路 "+(g+1);if(episodic&&confirmedOnly&&!sameEpisode(wanted,ep[0],flag+" "+title))continue;out.add(new Route(flag,ep[0],ep[1]));if(out.size()>=1000)return out;}return out;}
 static List<Route> alternatives(String flags,String groups,String selectedName,String selectedValue){ArrayList<Route> out=new ArrayList<>();HashSet<String> seen=new HashSet<>();seen.add(selectedValue);String key=episodeKey(selectedName);String[] names=flags.split("\\$\\$\\$",-1),lines=groups.split("\\$\\$\\$",-1);for(int g=0;g<lines.length&&out.size()<3;g++)for(String item:lines[g].split("#")){String[] ep=item.split("\\$",2);if(ep.length==2&&!ep[1].isEmpty()&&!key.isEmpty()&&key.equals(episodeKey(ep[0]))&&seen.add(ep[1]))out.add(new Route(g<names.length?names[g]:"线路 "+(g+1),ep[0],ep[1]));if(out.size()>=3)break;}return out;}
 /** 影视仓详情里的全部剧集。同一集只留第一条线路，不受换源列表 1000 条上限影响。正在播放的那一集用播放页 id，方便单选对上。 */
 static JSONArray episodeChoices(String flagText,String groupText,String playingId,String playingName){JSONArray out=new JSONArray();HashSet<String> seen=new HashSet<>();if(flagText==null)flagText="";if(groupText==null)groupText="";String[] flags=flagText.split("\\$\\$\\$",-1),groups=groupText.split("\\$\\$\\$",-1);String playing=playingName==null?"":episodeKey(playingName);try{for(int g=0;g<groups.length;g++)for(String encoded:groups[g].split("#")){String[] ep=encoded.split("\\$",2);if(ep.length<2||ep[1].isEmpty())continue;String flag=g<flags.length?flags[g]:"线路 "+(g+1);String key=episodeKey(ep[0]);if(key.isEmpty()||!seen.add(key))continue;Episode parsed=episode(ep[0],flag);String id="tv:"+key;if(!playing.isEmpty()&&playing.equals(key)&&playingId!=null&&!playingId.isEmpty())id=playingId;JSONObject row=new JSONObject().put("id",id).put("title",ep[0]).put("fusion.flag",flag).put("fusion.value",ep[1]).put("fusion.name",ep[0]);if(parsed.season>=0)row.put("season",parsed.season);if(parsed.number>0)row.put("episode",parsed.number);out.put(row);if(out.length()>=3000)return out;}}catch(JSONException ignored){}return out;}
}
